INSERT INTO ai_analysis (
    user_id, snapshot_id, simulation_id, analysis_type, result_json,
    input_data_hash, model_name, prompt_version, generation_source
) VALUES (
    #{userId}, #{snapshotId}, #{simulationId}, #{analysisType}, #{resultJson},
    #{inputDataHash}, #{modelName}, #{promptVersion}, #{generationSource}
)

mapper.select:
SELECT 
FROM ai_analysis a
WHERE a.analysis_id = #{analysisId}
  AND a.user_id = #{userId}

